  `file_size` int(11) NOT NULL COMMENT 'Tamanho do ficheiro em bytes',
  `is_primary` tinyint(1) DEFAULT 0 COMMENT 'Se é a imagem principal do produto',
  `display_order` int(11) DEFAULT 0 COMMENT 'Ordem de exibição',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_product_id` (`product_id`),
  KEY `idx_display_order` (`display_order`),
  KEY `idx_is_primary` (`is_primary`),
  CONSTRAINT `product_images_ibfk_1` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=32 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Imagens dos produtos armazenadas como BLOB';

